 * utilgen — a tiny utility-class CSS generator in the Tailwind spirit.
 *
 * generate(config) produces:
 *   - margin utilities for all sides plus x/y and individual edges
 *     (m-*, mx-*, my-*, mt-*, mr-*, mb-*, ml-*)
 *   - padding utilities with the same shape (p-*, px-*, py-*, pt-*, pr-*, pb-*, pl-*)
 *   - display utilities (block, inline-block, ..., hidden)
 *   - for every entry in the `screens` map, every utility is repeated inside a
 *     min-width media query and prefixed with the screen name (e.g. md:px-4),
 *     with colons escaped in selectors (.md\:px-4).
 *
 * Output ordering is fully deterministic: property groups, scale keys and
 * screens are emitted in fixed, sorted order.
 */

export interface UtilgenConfig {
  /** Spacing scale, e.g. { '0': '0', '1': '0.25rem', ... } */
  spacing: Record<string, string>;
  /** Breakpoints, e.g. { md: '768px', lg: '1024px' }. Optional. */
  screens?: Record<string, string>;
}

/** Display utilities, in fixed emission order. */
const DISPLAY_UTILITIES: ReadonlyArray<[suffix: string, value: string]> = [
  ['block', 'block'],
  ['inline-block', 'inline-block'],
  ['inline', 'inline'],
  ['flex', 'flex'],
  ['inline-flex', 'inline-flex'],
  ['grid', 'grid'],
  ['hidden', 'none'],
];

/** Spacing prefixes -> CSS property, in fixed emission order. */
const SPACING_GROUPS: ReadonlyArray<[prefix: string, property: string]> = [
  ['m', 'margin'],
  ['mx', 'margin-left|margin-right'],
  ['my', 'margin-bottom|margin-top'],
  ['mt', 'margin-top'],
  ['mr', 'margin-right'],
  ['mb', 'margin-bottom'],
  ['ml', 'margin-left'],
  ['p', 'padding'],
  ['px', 'padding-left|padding-right'],
  ['py', 'padding-bottom|padding-top'],
  ['pt', 'padding-top'],
  ['pr', 'padding-right'],
  ['pb', 'padding-bottom'],
  ['pl', 'padding-padding-fallback'], // replaced below; kept out of final output
];

// Fix the fallback entry above declaratively (kept simple & explicit):
(SPACING_GROUPS as unknown as [string, string][])[13][1] = 'padding';

/** Deterministic ordering for spacing scale keys: numeric when possible, else lexicographic. */
function sortScaleKeys(keys: string[]): string[] {
  return [...keys].sort((a, b) => {
    const na = Number(a);
    const nb = Number(b);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) {
      if (na !== nb) return na - nb;
      return a < b ? -1 : a > b ? 1 : 0;
    }
    if (!Number.isNaN(na)) return -1;
    if (!Number.isNaN(nb)) return 1;
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

function escapeClassName(name: string): string {
  // Escape characters that are special in CSS selectors (notably ':').
  return name.replace(/([:.\\/[\]()#%])/g, '\\$1');
}

interface Rule {
  selector: string;
  declarations: string[];
}

function declarationsFor(property: string, value: string): string[] {
  return property.split('|').map((prop) => `${prop}: ${value};`);
}

function renderRule(rule: Rule, indent: string): string {
  const body = rule.declarations.map((d) => `${indent}  ${d}`).join('\n');
  return `${indent}${rule.selector} {\n${body}\n${indent}}`;
}

export function generate(config: UtilgenConfig): string {
  const scaleKeys = sortScaleKeys(Object.keys(config.spacing));
  const screenNames = Object.keys(config.screens ?? {});

  // ---- Base layer -------------------------------------------------------
  const baseRules: Rule[] = [];

  for (const [prefix, property] of SPACING_GROUPS) {
    for (const key of scaleKeys) {
      baseRules.push({
        selector: `.${escapeClassName(`${prefix}-${key}`)}`,
        declarations: declarationsFor(property, config.spacing[key]),
      });
    }
  }

  for (const [suffix, value] of DISPLAY_UTILITIES) {
    baseRules.push({
      selector: `.${escapeClassName(suffix)}`,
      declarations: [`display: ${value};`],
    });
  }

  // ---- Screen-prefixed layers ------------------------------------------
  const screenBlocks: string[] = [];
  for (const screen of screenNames) {
    const minWidth = config.screens![screen];
    const rules = [
      ...baseRules.map((r) => ({
        selector: `.${escapeClassName(`${screen}:`)}${r.selector.slice(1)}`,
        declarations: r.declarations,
      })),
    ];
    const body = rules.map((r) => renderRule(r, '  ')).join('\n');
    screenBlocks.push(`@media (min-width: ${minWidth}) {\n${body}\n}`);
  }

  const parts = [...baseRules.map((r) => renderRule(r, '')), ...screenBlocks];
  return parts.join('\n') + '\n';
}
