result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/utilgen/tests/utilgen.test.ts", "content": "import { describe, expect, it } from 'vitest';
import postcss, { type ChildNode, type Declaration, type Rule as PostcssRule } from 'postcss';
import { generate } from '../src/index';

const spacing = {
  '0': '0',
  '1': '0.25rem',
  '2': '0.5rem',
  '4': '1rem',
  '8': '2rem',
};

const screens = {
  sm: '640px',
  md: '768px',
};

const config = { spacing, screens };

/** Parse CSS and return top-level nodes. */
function parse(css: string) {
  return postcss.parse(css);
}

function isRule(node: ChildNode): node is PostcssRule {
  return node.type === 'rule';
}

/** All rule nodes in the tree (root level + nested inside at-rules). */
function allRules(root: postcss.Root): PostcssRule[] {
  const rules: PostcssRule[] = [];
  root.walkRules((rule) => rules.push(rule));
  return rules;
}

describe('generate', () => {
  it('matches the snapshot for the fixed config', () => {
    expect(generate(config)).toMatchSnapshot();
  });

  it('is deterministic across calls', () => {
    expect(generate(config)).toBe(generate(config));
  });

  it('produces exactly sides × scale spacing rules per layer', () => {
    const css = generate(config);
    const root = parse(css);

    // 14 prefixes: m, mx, my, mt, mr, mb, ml, p, px, py, pt, pr, pb, pl
    const spacingPrefixes = 14;
    const scaleKeys = Object.keys(spacing).length;
    const displayCount = 7; // block, inline-block, inline, flex, inline-flex, grid, hidden
    const expectedBase = spacingPrefixes * scaleKeys + displayCount;

    const topLevelRules = root.nodes.filter(isRule);
    expect(topLevelRules.length).toBe(expectedBase);

    // Each screen layer repeats the exact same number of utilities.
    const mediaBlocks = root.nodes.filter(
      (n): n is postcss.AtRule => n.type === 'atrule' && (n as postcss.AtRule).name === 'media',
    );
    expect(mediaBlocks.length).toBe(Object.keys(screens).length);
    for (const media of mediaBlocks) {
      const nestedRules = media.nodes!.filter(isRule);
      expect(nestedRules.length).toBe(expectedBase);
    }

    // Total across the whole sheet.
    expect(allRules(root).length).toBe(expectedBase * (Object.keys(screens).length + 1));
  });

  it('emits every margin/padding side combination with the right declaration', () => {
    const root = parse(generate(config));

    const expected: Array<[string, string[]]> = [
      ['m-2', ['margin: 0.5rem;']],
      ['mx-8', ['margin-left: 2rem;', 'margin-right: 2rem;']],
      ['my-1', ['margin-top: 0.25rem;', 'margin-bottom: 0.25rem;']],
      ['mt-4', ['margin-top: 1rem;']],
      ['mr-1', ['margin-right: 0.25rem;']],
      ['mb-0', ['margin-bottom: 0;']],
      ['ml-8', ['margin-left: 2rem;']],
      ['p-2', ['padding: 0.5rem;']],
      ['px-8', ['padding-left: 2rem;', 'padding-right: 2rem;']],
      ['py-1', ['padding-top: 0.25rem;', 'padding-bottom: 0.25rem;']],
      ['pt-4', ['padding-top: 1rem;']],
      ['pr-1', ['padding-right: 0.25rem;']],
      ['pb-0', ['padding-bottom: 0;']],
      ['pl-8', ['padding-left: 2rem;']],
    ];

    for (const [cls, decls] of expected) {
      const rule = root.nodes.find(
        (n) => isRule(n) && n.selector === `.${cls}`,
      ) as PostcssRule | undefined;
      expect(rule, `missing base rule .${cls}`).toBeDefined();
      const actual = rule!.nodes.map((d) => `${(d as Declaration).prop}: ${(d as Declaration).value};`);
      expect(actual, `declarations for .${cls}`).toEqual(decls);
    }
  });

  it('emits display utilities', () => {
    const root = parse(generate(config));
    const bySelector = new Map<string, string>();
    for (const node of root.nodes.filter(isRule)) {
      const decl = node.nodes[0] as Declaration;
      bySelector.set(node.selector, `${decl.prop}:${decl.value}`);
    }
    expect(bySelector.get('.block')).toBe('display:block');
    expect(bySelector.get('.inline-block')).toBe('display:inline-block');
    expect(bySelector.get('.inline')).toBe('display:inline');
    expect(bySelector.get('.flex')).toBe('display:flex');
    expect(bySelector.get('.grid')).toBe('display:grid');
    expect(bySelector.get('.hidden')).toBe('display:none');
  });

  it('places md variants inside the correct media query', () => {
    const root = parse(generate(config));

    for (const [screen, minWidth] of Object.entries(screens)) {
      const media = root.nodes.find(
        (n) =>
          n.type === 'atrule' &&
          (n as postcss.AtRule).name === 'media' &&
          (n as postcss.AtRule).params === `(min-width: ${minWidth})`,
      ) as postcss.AtRule | undefined;
      expect(media, `@media (min-width: ${minWidth})`).toBeDefined();

      const nestedSelectors = media!.nodes!.filter(isRule).map((r) => r.selector);

      // Every prefixed selector lives inside this media query...
      const expectedPrefix = `.${screen}\\:`;
      const prefixedInside = nestedSelectors.filter((s) => s.startsWith(expectedPrefix));
      expect(prefixedInside.length).toBeGreaterThan(0);

      // ...and no prefixed selector for this screen lives anywhere else.
      const outsideCount = allRules(root).filter(
        (r) => r.selector.startsWith(expectedPrefix) && r.parent !== media,
      ).length;
      expect(outsideCount).toBe(0);

      // Spot-check a fully escaped variant and its declaration.
      const px4 = media!.nodes!.find(
        (n) => isRule(n) && n.selector === `.${screen}\\:px-4`,
      ) as PostcssRule | undefined;
      expect(px4).toBeDefined();
      const decls = px4!.nodes as Declaration[];
      expect(decls.map((d) => d.prop)).toEqual(['padding-left', 'padding-right']);
      expect(decls.every((d) => d.value === '1rem')).toBe(true);
    }
  });
});
"})
